<?php
namespace Tests\Feature;
use App\Services\Marketing\{MarketingVideoRoutes,MarketingEvolinkClient,MarketingStoryboardProduction,MarketingEconomyVideoPolicy};
use Illuminate\Support\Facades\Http;
use Tests\TestCase;
class MarketingEconomyVideoTransportTest extends TestCase {
 private function configModels():void {$price=['version'=>'fake-economic','cap_microusd'=>400000,'credit_usd'=>10/650,'access_verified_at'=>'fixture','pricing_verified_at'=>'fixture'];config(['marketing.native.api_key'=>'fixture-not-real','marketing.storyboard.roles.video'=>$price+['model'=>'seedance-1.5-pro','tiers'=>['ordinary']],'marketing.storyboard.video_models'=>['doubao-seedance-1.0-pro-fast'=>array_replace($price,['model'=>'doubao-seedance-1.0-pro-fast','cap_microusd'=>100000,'source_has_audio'=>false,'source_audio_verified_at'=>'fixture'])]]);}
 public function test_fake_submit_and_usage_query_for_each_model_have_no_retry_or_unknown_fields():void {
  $this->configModels();Http::fake(['https://api.evolink.ai/v1/videos/generations'=>Http::sequence()->push(['id'=>'fake-15','usage'=>['credits_reserved'=>21.3408]])->push(['id'=>'fake-fast','usage'=>['credits_reserved'=>4.5]]),'https://api.evolink.ai/v1/tasks/*'=>Http::response(['id'=>'fake-15','status'=>'completed','usage'=>['credits_used'=>21.3408],'results'=>['https://files.evolink.ai/fake.mp4']])]);
  $svc=app(MarketingVideoRoutes::class);$scene=['seconds'=>6,'presenter_required'=>true,'voiceover'=>'介绍货柜','frames'=>['start_frame'=>['person_presence'=>'visible']],'material_plan'=>['mode'=>'single_image','roles'=>['start_frame'],'reason'=>'AI安排人物口播','preferred_model'=>'seedance-1.5-pro']];
  $r=$svc->select($scene,'ordinary');$this->assertSame('seedance-1.5-pro',$r['video']['model']);
  $payload=$svc->payload(['model'=>$r['video']['model'],'prompt'=>'普通话女声说：“介绍货柜”。','duration'=>6,'quality'=>'720p','aspect_ratio'=>'9:16','generate_audio'=>true,'content_filter'=>true],$r);$task=app(MarketingEvolinkClient::class)->submit($payload+['image_urls'=>['https://files.evolink.ai/start.png','https://files.evolink.ai/end.png']]);$out=app(MarketingEvolinkClient::class)->query($task['id']);$this->assertEquals(21.3408,$out['usage']['credits_used']);
  $scene['seconds']=5;$scene['presenter_required']=false;$scene['voiceover']='';$scene['frames']['start_frame']['person_presence']='absent';$scene['material_plan']['shot_kind']='product_broll';$scene['material_plan']['preferred_model']='doubao-seedance-1.0-pro-fast';$r=$svc->select($scene,'ordinary');$this->assertSame('doubao-seedance-1.0-pro-fast',$r['video']['model']);$payload=$svc->payload(['model'=>$r['video']['model'],'prompt'=>'商品空镜保持货柜外观。','duration'=>5,'quality'=>'720p','aspect_ratio'=>'9:16','generate_audio'=>false,'content_filter'=>true],$r);app(MarketingEvolinkClient::class)->submit($payload+['image_urls'=>['https://files.evolink.ai/product.png']]);
  Http::assertSentCount(3);Http::assertSent(fn($req)=>$req->method()==='POST'&&$req['model']==='seedance-1.5-pro'&&$req['generate_audio']===true&&!isset($req['content_filter']));Http::assertSent(fn($req)=>$req->method()==='POST'&&$req['model']==='doubao-seedance-1.0-pro-fast'&&!isset($req['generate_audio'])&&!isset($req['prompt_extend'])&&$req['aspect_ratio']==='9:16');
 }
 public function test_missing_economy_price_does_not_fall_back_to_standard():void {
  $this->configModels();config(['marketing.storyboard.roles.video'=>['model'=>'seedance-2.0-image-to-video','version'=>'fake','cap_microusd'=>1500000,'credit_usd'=>10/650,'access_verified_at'=>'fixture','pricing_verified_at'=>'fixture']]);Http::preventStrayRequests();$scene=['seconds'=>6,'voiceover'=>'口播','presenter_required'=>true,'material_plan'=>['mode'=>'first_last_frames','roles'=>['start_frame','end_frame'],'reason'=>'AI要求首尾帧','preferred_model'=>'seedance-1.5-pro']];
  try{app(MarketingVideoRoutes::class)->select($scene,'ordinary');$this->fail('silently upgraded');}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){$this->assertSame(423,$e->getStatusCode());}Http::assertNothingSent();
 }
 public function test_ordinary_models_are_not_silently_used_for_other_tiers():void {$this->configModels();Http::preventStrayRequests();$scene=['seconds'=>6,'voiceover'=>'口播','presenter_required'=>true,'material_plan'=>['mode'=>'single_image','roles'=>['start_frame'],'reason'=>'人物口播']];$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);app(MarketingVideoRoutes::class)->select($scene,'professional');}
}
